<?php if($data['products'] && mysqli_num_rows($data['products'])>0) { ?><div class="products"><?php while($product=mysqli_fetch_assoc($data['products'])) { ?><article class="product-card"><a class="product-image" href="store.php?url=Storefront/ChiTiet/<?php echo rawurlencode($product['MaSP']); ?>"><?php if(!empty($product['HinhAnh'])) { ?><img src="Public/Images/<?php echo rawurlencode($product['HinhAnh']); ?>" alt="<?php echo htmlspecialchars($product['TenSP'],ENT_QUOTES,'UTF-8'); ?>"><?php } else { ?><span class="muted">Ch&#432;a c&#243; h&#236;nh &#7843;nh</span><?php } ?></a><div class="product-copy"><div class="muted"><?php echo htmlspecialchars($product['TenDM'] ?? 'Ch&#432;a ph&#226;n lo&#7841;i',ENT_QUOTES,'UTF-8'); ?></div><h2><a href="store.php?url=Storefront/ChiTiet/<?php echo rawurlencode($product['MaSP']); ?>"><?php echo htmlspecialchars($product['TenSP'],ENT_QUOTES,'UTF-8'); ?></a></h2><div class="price"><?php echo number_format((float)$product['GiaBan'],0,',','.'); ?> &#8363;</div><div class="stock"><?php echo (int)$product['SoLuongTon']>0?'C&#242;n '.(int)$product['SoLuongTon'].' s&#7843;n ph&#7849;m':'T&#7841;m h&#7871;t h&#224;ng'; ?></div><div class="product-actions"><a class="button secondary" href="store.php?url=Storefront/ChiTiet/<?php echo rawurlencode($product['MaSP']); ?>">Chi ti&#7871;t</a><form method="post" action="store.php?url=Cart/Add/<?php echo rawurlencode($product['MaSP']); ?>"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['shop_csrf'],ENT_QUOTES,'UTF-8'); ?>"><button class="button" type="submit" <?php echo (int)$product['SoLuongTon']<1?'disabled':''; ?>>Th&#234;m gi&#7887;</button></form></div></div></article><?php } ?></div><?php } else { ?><div class="empty">Kh&#244;ng t&#236;m th&#7845;y s&#7843;n ph&#7849;m ph&#249; h&#7907;p.</div><?php } ?>
